/* @lc app=leetcode id=959 lang=kotlin */ class Solution { fun set(g: Array<IntArray>, i: Int, j: Int) { g[i][j] = 1 } fun fill(g: Array<IntArray>, i: Int, j: Int) = java.util.ArrayDeque(listOf(intArrayOf(i, j))).also { set(g, i, j) }.let { q -> generateSequence { q.poll() }.forEach { p -> listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) }.filter { it[0] in g.indices && it[1] in g.indices && g[it[0]][it[1]] == 0 }.forEach { x -> set(g, x[0], x[1]).also { q.add(x) } } } } fun regionsBySlashes(grid: Array<String>): Int = Array(3 * grid.size) { IntArray(3 * grid.size) }.also { g -> grid.indices.forEach { i -> grid[i].forEachIndexed { j, c -> if (c != ' ') (0..2).forEach { r -> g[3 * i + r][3 * j + if (c == '/') 2 - r else r] = 1 } } } }.let { g -> (0 until g.size * g.size).count { k -> g[k / g.size][k % g.size] == 0 && fill(g, k / g.size, k % g.size).let { true } } } }